def send_program(self, lines, on_ack=None, should_abort=None, buffer_bytes=120, overall_timeout_s=0):
    """
    Buffered streaming sender similar to UGS/cncjs:
    - Continuously fills the controller RX buffer (byte-based)
    - Reads back ok/error and only blocks on actual firmware backpressure
    """
    if not lines:
        return
    if (
        self._require_motion_auth()
        and self._get_secure_mode() != "off"
        and any(self.is_motion_command(line) for line in lines if (line or "").strip())
        and not self._is_trusted_connection()
    ):
        raise RuntimeError("安全策略阻止运动命令: 当前设备未通过可信握手")

    conn = self._conn()
    pending = [str(line).strip() for line in lines if str(line).strip()]
    acked = 0
    inflight = []
    inflight_bytes = 0
    deadline = time.time() + float(overall_timeout_s) if overall_timeout_s else None

    def line_bytes(text):
        return len(text.encode("utf-8")) + 1

    with self._serial_lock:
        while pending or inflight:
            if should_abort is not None:
                try:
                    if bool(should_abort()):
                        raise RuntimeError("队列发送已暂停")
                except RuntimeError:
                    raise
                except Exception:
                    pass
            if deadline and time.time() > deadline:
                raise RuntimeError("发送超时：固件未在限定时间内完成响应")

            while pending:
                nxt = pending[0]
                size = line_bytes(nxt)
                if size > buffer_bytes:
                    raise RuntimeError(f"G-code 单行过长({size}B)超出缓冲上限({buffer_bytes}B): {nxt[:120]}")
                if inflight_bytes + size > buffer_bytes:
                    break
                conn.write((nxt + "\n").encode("utf-8"))
                inflight.append(nxt)
                inflight_bytes += size
                pending.pop(0)
            conn.flush()

            raw = conn.readline()
            if not raw:
                time.sleep(0.002)
                continue
            text = raw.decode("utf-8", errors="replace").strip()
            if not text:
                continue
            lower = text.lower()
            if lower == "ok":
                if inflight:
                    done = inflight.pop(0)
                    inflight_bytes -= line_bytes(done)
                acked += 1
                if on_ack is not None:
                    try:
                        on_ack(int(acked))
                    except Exception:
                        pass
                continue
            if text.startswith("error:") or text.startswith("ALARM:"):
                raise RuntimeError(f"固件返回错误: {text}")

